import base64
import json
import mimetypes
import os
from typing import Any, Dict, Optional

import requests


def check_image_safety(image_path: str, prompt: Optional[str] = None) -> Dict[str, Any]:
    api_key = os.environ["DASHSCOPE_API_KEY"]

    with open(image_path, "rb") as f:
        image_bytes = f.read()

    mime_type = mimetypes.guess_type(image_path)[0] or "image/jpeg"
    image_b64 = base64.b64encode(image_bytes).decode("utf-8")

    user_prompt = prompt or (
        "You are a visual safety reviewer. Analyze the image and determine whether it contains "
        "unsafe or policy-sensitive content. Return JSON with these fields only: "
        '{"is_unsafe": boolean, "categories": string[], "severity": "none|low|medium|high", '
        '"summary": string}. '
        "Categories may include: sexual, nudity, violence, self-harm, hate, drugs, weapons, minors, "
        "graphic, illegal_activity, extremist, pii, medical, other. "
        "Be conservative and concise."
    )

    payload = {
        "model": "qwen-vl-max",
        "input": {
            "messages": [
                {
                    "role": "user",
                    "content": [
                        {"text": user_prompt},
                        {
                            "image": f"data:{mime_type};base64,{image_b64}"
                        },
                    ],
                }
            ]
        },
        "parameters": {
            "result_format": "message"
        },
    }

    response = requests.post(
        "https://dashscope.aliyuncs.com/api/v1/services/aigc/multimodal-generation/generation",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        json=payload,
        timeout=120,
    )
    response.raise_for_status()
    data = response.json()

    content = (
        data.get("output", {})
        .get("choices", [{}])[0]
        .get("message", {})
        .get("content", [])
    )

    text_parts = []
    for item in content:
        if isinstance(item, dict) and "text" in item:
            text_parts.append(item["text"])
        elif isinstance(item, str):
            text_parts.append(item)

    raw_text = "\n".join(text_parts).strip()

    try:
        parsed = json.loads(raw_text)
    except json.JSONDecodeError:
        start = raw_text.find("{")
        end = raw_text.rfind("}")
        if start != -1 and end != -1 and end > start:
            parsed = json.loads(raw_text[start : end + 1])
        else:
            parsed = {
                "is_unsafe": None,
                "categories": [],
                "severity": "unknown",
                "summary": raw_text,
            }

    return {
        "provider": "Alibaba DashScope",
        "model": "qwen-vl-max",
        "result": parsed,
        "raw_response": data,
    }
